return {bsnpc0601={id="bsnpc0601",dsc="王二蛋和王丞丞的妹妹，从小乖巧懂事，王蔷蔷一直都由她照顾。",sex="女",age=7,looks=20,showequip={},withCorpse=0},bsnpc0602={id="bsnpc0602",dsc="王二蛋、王丞丞和王梁梁的弟弟，王家最小的孩子。十分的天真无邪。",sex="男",age=5,looks=20,showequip={},withCorpse=0},bsnpc0603={id="bsnpc0603",dsc="一名居住在平安小镇外的庄稼人。",sex="男",age=21,looks=17,showequip={},withCorpse=0},bsnpc0604={id="bsnpc0604",dsc="一名正在打盹的农夫。",sex="男",age=51,looks=17,showequip={},withCorpse=0},bsnpc0605={id="bsnpc0605",dsc="平安小镇的一名居民。",sex="男",age=21,looks=20,showequip={},withCorpse=0},bsnpc0606={id="bsnpc0606",dsc="平安小镇的一名居民。",sex="男",age=21,looks=17,showequip={},withCorpse=0},bsnpc0607={id="bsnpc0607",dsc="一名书生。",sex="男",age=21,looks=20,showequip={},withCorpse=0},bsnpc0608={id="bsnpc0608",dsc="一名大户人家的小姐。",sex="女",age=18,looks=20,showequip={},withCorpse=0},bsnpc0609={id="bsnpc0609",dsc="他手里拿着不少东西。",sex="男",age=21,looks=17,showequip={},withCorpse=0},bsnpc0610={id="bsnpc0610",dsc="一名云游四海的文人。",sex="男",age=21,looks=20,showequip={},withCorpse=0},bsnpc0611={id="bsnpc0611",dsc="他是一名侠士。",sex="男",age=31,looks=17,showequip={},withCorpse=0},bsnpc0612={id="bsnpc0612",sex="男",age=21,looks=17,showequip={},withCorpse=0},bsnpc0613={id="bsnpc0613",dsc="天启帮聚义堂的副堂主，章作之的手下。对章作之忠心耿耿，并在他离开之后为他管理聚义堂。",sex="男",age=21,looks=25,showequip={},withCorpse=0},bsnpc0614={id="bsnpc0614",dsc="一名平安小镇的居民。",sex="女",age=31,looks=17,showequip={},withCorpse=0},bsnpc0615={id="bsnpc0615",dsc="一名平安小镇的居民。",sex="男",age=51,looks=17,showequip={},withCorpse=0},bsnpc0616={id="bsnpc0616",dsc="一名平安小镇的居民。",sex="男",age=21,looks=17,showequip={},withCorpse=0},bsnpc0617={id="bsnpc0617",dsc="一名平安小镇的居民。",sex="男",age=31,looks=17,showequip={},withCorpse=0},bsnpc0618={id="bsnpc0618",dsc="附近小有名气的才女。",sex="女",age=21,looks=20,showequip={},withCorpse=0},bsnpc0619={id="bsnpc0619",dsc="他负手而立，表情冷淡地看着众人。",sex="男",age=17,looks=27,showequip={},withCorpse=0},bsnpc0620={id="bsnpc0620",dsc="浮云寺的僧侣。",sex="男",age=17,looks=20,showequip={},withCorpse=0},bsnpc0621={id="bsnpc0621",dsc="浮云寺的僧侣。",sex="男",age=21,looks=20,showequip={},withCorpse=0},bsnpc0622={id="bsnpc0622",dsc="他为人十分老实，少年时本打算考取功名，可惜家道中落，于是学着别人落草为寇，但因为十分老实被赶出了山寨，如今耕田过日子倒也自在。",sex="男",age=29,looks=16,showequip={},withCorpse=0},bsnpc0623={id="bsnpc0623",dsc="他昔年曾是一名刀客，后被仇人追杀身负重伤，为平安小镇的居民所救，后在此安家退隐江湖。",sex="男",age=45,looks=15,showequip={},withCorpse=0},bsnpc0624={id="bsnpc0624",dsc="她是平安小镇的居民，在家中排行第二，早年嫁给了一个江湖浪人，后夫君远走江湖再未归来。",sex="女",age=44,looks=18,showequip={},withCorpse=0},bsnpc0625={id="bsnpc0625",dsc="她身着破旧的粗布衣，身上挂着用线绳穿好的十多双大大小小的草鞋、布鞋。",sex="女",age=45,looks=18,showequip={},withCorpse=0},bsnpc0626={id="bsnpc0626",dsc="他一副书生模样，但手中却拿着一个沉重的流星锤，虽是有模有样的耍着，但因气力不足，下盘紊乱，常常将流星锤砸入四周的石板，引得周围人群纷纷避让。",sex="男",age=17,looks=20,showequip={},withCorpse=0},bsnpc0627={id="bsnpc0627",dsc="他是平安小镇中出了名的恶霸，仗着家中有人当官平日里作威作福。",sex="男",age=28,looks=18,showequip={},withCorpse=0},bsnpc0628={id="bsnpc0628",dsc="他梳着一个长长的小辫，手上拿着一把桃木短剑，面目严肃，颇有几分“大侠”的样子。",sex="男",age=11,looks=19,showequip={},withCorpse=0},bsnpc0629={id="bsnpc0629",dsc="他时常喝得酩酊大醉，听说多年前也曾是浪荡江湖的剑客，后来不知为何埋剑藏名隐居于平安小镇。",sex="男",age=45,looks=20,showequip={},withCorpse=0},bsnpc0630={id="bsnpc0630",dsc="他手中拿着几个铜板，正盯着前方的菜来饭馆，不时往前走两步，又退两步，看起来十分纠结。",sex="男",age=23,looks=17,showequip={},withCorpse=0},bsnpc0631={id="bsnpc0631",dsc="他是平安小镇的居民，身穿粗布长衣，手中拿着一个鸟笼。鸟笼里关着一只翠鸟，毛色翠兰，十分夺目。",sex="男",age=35,looks=16,showequip={},withCorpse=0},bsnpc0632={id="bsnpc0632",dsc="他自称是响当当的江湖大侠，身具传奇，懂得天下所有武功。他手中时常抱着剑，装成一副十分冷酷的样子。",sex="男",age=35,looks=18,showequip={},withCorpse=0},bsnpc0633={id="bsnpc0633",dsc="他佝偻着背，手上拿着一个拐杖，正坐在路旁歇息。",sex="男",age=65,looks=15,showequip={},withCorpse=0},bsnpc0634={id="bsnpc0634",dsc="他是平安小镇的糖贩，家中养了无数蜜蜂，做出的糖极为甜蜜。他为人亲和，时常会把自己做的各色糖果赠予镇中孩童。",sex="男",age=32,looks=17,showequip={},withCorpse=0},bsnpc0635={id="bsnpc0635",dsc="她年轻时曾是武林中公认的美人，英雄迟暮，美人自然也有这么一天，自隐居平安小镇后，她除了自怜自哀以外成了统领平安小镇三姑六婆一起八卦的核心之人。",sex="女",age=45,looks=21,showequip={},withCorpse=0},bsnpc0636={id="bsnpc0636",dsc="平安小镇澡堂的掌柜。平日里会亲自上山采药来做药浴。",sex="男",age=59,looks=17,showequip={},withCorpse=0},bsnpc0637={id="bsnpc0637",sex="男",age=59,looks=17,showequip={},withCorpse=0},bsnpc0638={id="bsnpc0638",dsc="他是菜来饭馆的厨子，做得一手好菜，听说他为了哄重病的母亲开心，专门研制了蜜枣，十分香甜。",sex="男",age=55,looks=21,showequip={},withCorpse=0},rwnpc0601={id="rwnpc0601",dsc="他一身黑衣，蓬头垢面，不修边幅。",sex="男",age=56,looks=21,showequip={},withCorpse=0},rwnpc0602={id="rwnpc0602",dsc="虽是徐娘半老，但风韵犹存，落落大方的姿态更是叫人忍不住想亲近她。",sex="女",age=50,looks=20,showequip={},withCorpse=0},rwnpc0603={id="rwnpc0603",dsc="他是小镇的居民，穿着灰麻布衣，头上裹着布巾。",sex="男",age=38,looks=17,showequip={},withCorpse=0},rwnpc0604={id="rwnpc0604",dsc="是一名稚龄孩童，相比其他同龄的孩童，他的身材格外瘦小，但却长着一张白白净净的小脸，让大人们十分喜爱。",sex="男",age=8,looks=19,showequip={},withCorpse=0},rwnpc0605={id="rwnpc0605",dsc="他一身黑衣，收拾得十分爽利，一把长刀随意的放在身旁。",sex="男",age=56,looks=21,showequip={},withCorpse=0},rwnpc0606={id="rwnpc0606",dsc="是远近闻名的顽童。",sex="男",age=9,looks=17,showequip={},withCorpse=0},rwnpc0607={id="rwnpc0607",dsc="他就是李小刚，看起来很是乖巧，平日最爱和王小智一起玩闹。",sex="男",age=9,looks=17,showequip={},withCorpse=0},rwnpc0608={id="rwnpc0608",dsc="她着一身红裙，看样式不似中原人士，手脚带着银色铃镯，一行一动皆伴着清脆铃音。",sex="女",age=17,looks=21,showequip={},withCorpse=0}}00000